/* Save metrics learned by this TCP session.
   This function is called only, when TCP finishes successfully
   i.e. when it enters TIME-WAIT or goes from LAST-ACK to CLOSE.
 */
void tcp_update_metrics(struct sock *sk)
{
	struct tcp_sock *tp = tcp_sk(sk);
	struct dst_entry *dst = __sk_dst_get(sk);

	if (sysctl_tcp_nometrics_save)
		return;

	dst_confirm(dst);

	if (dst && (dst->flags & DST_HOST)) {
		const struct inet_connection_sock *icsk = inet_csk(sk);
		int m;

		if (icsk->icsk_backoff || !tp->srtt) {
			/* This session failed to estimate rtt. Why?
			 * Probably, no packets returned in time.
			 * Reset our results.
			 */
			if (!(dst_metric_locked(dst, RTAX_RTT)))
				dst_metric_set(dst, RTAX_RTT, 0);
			return;
		} else if (dst_metric_locked(dst, RTAX_RTT)) {
			return;
		}
		m = dst_metric_get(dst, RTAX_RTT);
		if (!m || m > tp->srtt) {
			/* This session gives us the best RTT.
			 * Use it to replace the current value.
			 */
			dst_metric_set(dst, RTAX_RTT, tp->srtt);
		}
		m = dst_metric_get(dst, RTAX_RTTVAR);
		if (!m || m > tp->mdev) {
			dst_metric_set(dst, RTAX_RTTVAR, tp->mdev);
		}
