	struct inet6_dev *idev;
	struct neighbour *neigh;
	struct netevent_redirect netevent;
	int on_link;

	rt = (struct rt6_info *) dst;
	dest = &rt->rt6i_dst.addr;
	src  = &rt->rt6i_src.addr;

	/* Locate the device for validating the redirect */
	idev = in6_dev_get(skb->dev);
	if (!idev)
		return;

	neigh = __neigh_lookup(&nd_tbl, &ipv6_hdr(skb)->saddr, skb->dev, 1);
	if (neigh) {
		read_lock_bh(&neigh->lock);
		on_link = !((neigh->nud_state & NUD_VALID) &&
			    !(neigh->nud_state & NUD_CONNECTED));
		read_unlock_bh(&neigh->lock);
		neigh_release(neigh);
	} else
		on_link = 0;

	if (!on_link) {
		if (net_ratelimit())
			printk(KERN_DEBUG "Redirect: destination is not on-link\n");
		in6_dev_put(idev);
