static void nand_write_buf16(struct nand_chip *chip, const uint8_t *buf,
			     int len)
{
	struct nand_chip *nand = chip;
	int i;
	uint16_t tbuf;

	for (i = 0; i < len; i += 2) {
		tbuf = *buf++;
		tbuf |= (*buf++) << 8;
		nand_write_word(nand, tbuf);
	}
}

static void nand_read_buf16(struct nand_chip *chip, uint8_t *buf, int len)
{
	struct nand_chip *nand = chip;
	int i;
	uint16_t tbuf;

	for (i = 0; i < len; i += 2) {
		tbuf = nand_read_word(nand);
		*buf++ = tbuf & 0xff;
		*buf++ = tbuf >> 8;
	}
}

static int nand_verify_buf16(struct nand_chip *chip, const uint8_t *buf,
